        }

        byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
        using (var sha256 = SHA256.Create())
        {
            for (int i = 0; i < passwordHashPasses; i++)
            {
                passwordBytes = sha256.ComputeHash(passwordBytes);
            }
        }

        byte[] decryptedData;
