using System;
using System.Text.Json;
using System.Text.Json.Serialization;

[AttributeUsage(AttributeTargets.Property, AllowMultiple = false)]
public class JsonAliasAttribute : Attribute
{
    public string Alias { get; }

    public JsonAliasAttribute(string alias)
    {
        Alias = alias;
    }
}

public class SampleClass
{
    [JsonAlias("id")]
    public int Identifier { get; set; }

    [JsonAlias("name")]
    public string FullName { get; set; }
}

public class Program
{
    public static void Main()
    {
        var sample = new SampleClass { Identifier = 1, FullName = "John Doe" };

        string json = SerializeToJson(sample);
        Console.WriteLine(json);

        SampleClass deserialized = DeserializeFromJson<SampleClass>(json);
        Console.WriteLine($"Identifier: {deserialized.Identifier}, FullName: {deserialized.FullName}");
    }

    public static string SerializeToJson<T>(T obj)
    {
        var options = new JsonSerializerOptions
        {
            Converters = { new JsonAliasConverter() }
        };
        return JsonSerializer.Serialize(obj, options);
    }

    public static T DeserializeFromJson<T>(string json)
    {
        var options = new JsonSerializerOptions
        {
            Converters = { new JsonAliasConverter() }
        };
        return JsonSerializer.Deserialize<T>(json, options);
    }
}

public class JsonAliasConverter : JsonConverter<object>
{
    public override object Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.PropertyName)
        {
            string propertyName = reader.GetString();
            var property = typeToConvert.GetProperties()
                .FirstOrDefault(p => p.GetCustomAttributes(typeof(JsonAliasAttribute), true)
                .Cast<JsonAliasAttribute>()
                .Any(attr => attr.Alias == propertyName));
            if (property != null)
            {
                return JsonSerializer.Deserialize(ref reader, property.PropertyType, options);
            }
        }
        return JsonSerializer.Deserialize(ref reader, typeToConvert, options);
    }

    public override void Write(Utf8JsonWriter writer, object value, JsonSerializerOptions options)
    {
        var type = value.GetType();
        foreach (var property in type.GetProperties())
        {
            var aliasAttribute = (JsonAliasAttribute)Attribute.GetCustomAttribute(property, typeof(JsonAliasAttribute));
            string propertyName = aliasAttribute?.Alias ?? property.Name;
            writer.WritePropertyName(propertyName);
            JsonSerializer.Serialize(writer, property.GetValue(value), options);
        }
    }
}
